const pad=n=>String(n).padStart(2,"0");
function dateKey(d){return `${d.getUTCFullYear()}-${pad(d.getUTCMonth()+1)}-${pad(d.getUTCDate())}`}
function parseDateKey(s){let [y,m,d]=s.split("-").map(Number);return new Date(Date.UTC(y,m-1,d,12))}
function mondayOf(d){d=new Date(Date.UTC(d.getUTCFullYear(),d.getUTCMonth(),d.getUTCDate(),12));let k=(d.getUTCDay()+6)%7;d.setUTCDate(d.getUTCDate()-k);return d}
