function berlinDateKey(d=new Date()){let parts=new Intl.DateTimeFormat("en-CA",{timeZone:"Europe/Berlin",year:"numeric",month:"2-digit",day:"2-digit"}).formatToParts(d),m=Object.fromEntries(parts.map(x=>[x.type,x.value]));return `${m.year}-${m.month}-${m.day}`}
function minToTime(m){let day=Math.floor(m/1440),x=((m%1440)+1440)%1440;return `${pad(Math.floor(x/60))}:${pad(x%60)}${day>0?" +"+day:""}`}
