function renameStop(x){if(!x)return "";let y=x;for(let i=0;i<6&&DATA.renames[y]&&DATA.renames[y]!==y;i++)y=DATA.renames[y];return y.replace("Park der Menschenr.","Park der Menschenrechte").replace("Laupendahl ZOB","Laupendahl Hbf/ZOB")}
function cleanLine(v){return !v||["Ausr","Einr","B","P"].includes(v)?null:String(v)}
function lineAt(run,min){let cur=null;for(const [t,v] of run.timeline){if(t>min)break;let c=cleanLine(v);if(c)cur=c}return cur}
