function groupStop(s){s=(s||"").toLowerCase();if(/zob|hauptbahnhof|hbf/.test(s))return"zentrum";if(/spryndorf/.test(s))return"spryndorf";if(/sisselsforst|oesdorf|essenberg/.test(s))return"sisselsforst";if(/griesbach/.test(s))return"griesbach";if(/hochtann/.test(s))return"hochtann";if(/kreuzing|karlsbader|hofberg|graf-von-galen|paul-ehrlich/.test(s))return"kreuzing";if(/reichbrück|nordbahnhof/.test(s))return"nord";if(/dotzheim|polkloh/.test(s))return"polkloh";return s.slice(0,18)}
function reliefKey(s){return renameStop(String(s||"" )).toLowerCase().replace(/\([^)]*(?:steig|p\s*\d|gleis)[^)]*\)/gi,"").replace(/\b(?:steig|bussteig|gleis)\s*\d+[a-z]?\b/gi,"").replace(/\bpausenpl\.?$/i,"").replace(/\s+/g," ").trim()}
function isReliefHotspot(s){let x=reliefKey(s);return /fachhochschule|botanischer garten|nordbahnhof|hauptbahnhof|hbf\/?zob|laupendahl zob|s-?bahnhof|s-bf|\bs\s*bahnhof\b|\s+s$/i.test(x)}
