async function nextEmployeeId(env){
  let max=DATA.employees.reduce((m,e)=>Math.max(m,Number(String(e.id).match(/R-(\d+)/)?.[1]||0)),0);
  let r=await env.DB.prepare(`SELECT employee_id FROM employee_records`).all();
  for(const row of r.results||[])max=Math.max(max,Number(String(row.employee_id||"").match(/R-(\d+)/)?.[1]||0));
  return `R-${String(max+1).padStart(4,"0")}`;
}
